for w,g,b in [('dabord','Выбран первый шаг: чтение сообщения.','Сначала обозначает первый шаг; затем — следующий, завтра — время.'),('ensuite','Следующим шагом назван ответ.','Затем обозначает следующий шаг; сначала меняет порядок, план на завтра не задаёт этот переход.'),('enfin','Ответ прямо обозначен как последний шаг.','В конце задаёт последний шаг; сначала меняет его роль, чтение — другое действие.'),('ouvrir','Выбрана просьба открыть книгу.','Закрыть — противоположное действие, читать сообщение — другая просьба.'),('fermer','Выбрана просьба закрыть дверь.','Открыть — противоположное действие, чтение книги не закрывает дверь.')]:W[w]['review_items'][1]['feedback']=fb(g,b)

